def with_title(items):
    """Her girdinin desenine kendi başlığını da ekler (parantez içi ve noktalama atılır): 'X nedir' sorusu desenden kaçmasın."""
    import re
    out = []
    for t, p, x in items:
        n = t.replace("İ", "i").replace("I", "ı").lower()
        n = re.sub(r"\([^)]*\)", " ", n)
        n = re.sub(r"['’]\w*", "", n)
        n = " ".join(re.sub(r"[^\w\sçğıöşü]", " ", n).split())
        out.append((t, p + "|" + re.escape(n), x) if n else (t, p, x))
    return sorted(out, key=lambda e: -len(e[0]))      # uzun başlıklar önce: 'Fonksiyon' başlığı 'Üstel fonksiyon' sorusunu çalmasın
